      def add_monthly_table(orders)
        @message.push "<hr>"
        @message.push "<b style='font-size: 13px; font-weight: bold;'>Dekretowane zamówienia</b>"
        @message.push "<hr>"
        @message.push "<table class='blueTable'>"

        @message.push "<tr>"
        @message.push "<th>"
        @message.push "Nazwa zamówienia"
        @message.push "</th>"
        @message.push "<th>"
        @message.push "Przyjęte w ostatnim miesiącu"
        @message.push "</th>"
        @message.push "<th>"
        @message.push "Wszystkie niezarejestrowane, ale przyjęte z całego zamówienia"
        @message.push "</th>"
        @message.push "<th>"
        @message.push "Wszystkie przyjęte / całe zamówienie"
        @message.push "</th>"
        @message.push "</tr>"

        orders.each do |order|
          @message.push "<tr>"
          @message.push "<td>"
          @message.push order.name
          @message.push "</td>"
          @message.push "<td>"
          @message.push order.acc_count
          @message.push "</td>"
          @message.push "<td>"
          @message.push order.nonreg_count
          @message.push "</td>"
          @message.push "<td>"
          @message.push order.balance
          @message.push "</td>"
          @message.push "</tr>"
        end

        @message.push "</table>"
        @message.push "<hr>"
      end

      def add_general_table(orders)
        @message.push "<br>"
        @message.push "<hr>"
        @message.push "<b style='font-size: 13px; font-weight: bold;'>Inne zamówienia</b>"
        @message.push "<hr>"
        @message.push "<table class='blueTable'>"

        @message.push "<tr>"
        @message.push "<th>"
        @message.push "Nazwa zamówienia"
        @message.push "</th>"
        @message.push "<th>"
        @message.push "W drodze do labu"
        @message.push "</th>"
        @message.push "<th>"
        @message.push "Autoryzowane"
        @message.push "</th>"
        @message.push "<th>"
        @message.push "Wszystkie niezarejestrowane, ale przyjęte"
        @message.push "</th>"
        @message.push "<th>"
        @message.push "Wszystkie anulowane"
        @message.push "</th>"
        @message.push "<th>"
        @message.push "Wszystkie przyjęte / całe zamówienie"
        @message.push "</th>"
        @message.push "</tr>"

        orders.each do |order|
          @message.push "<tr>"
          @message.push "<td>"
          @message.push order.name
          @message.push "</td>"
          @message.push "<td>"
          @message.push order.online_count
          @message.push "</td>"
          @message.push "<td>"
          @message.push order.authorized
          @message.push "</td>"
          @message.push "<td>"
          @message.push order.nonreg_count
          @message.push "</td>"
          @message.push "<td>"
          @message.push order.cancelled
          @message.push "</td>"
          @message.push "<td>"
          @message.push order.balance
          @message.push "</td>"
          @message.push "</tr>"
        end

        @message.push "</table>"
        @message.push "<hr>"
      end

      def add_omega_table(samples)
        @message.push "<br>"
        @message.push "<hr>"
        @message.push "<b style='font-size: 13px; font-weight: bold;'>Kwasy OMEGA (tylko Diagnostyka Precyzyjna)</b>"
        @message.push "<hr>"
        @message.push "<table class='blueTable'>"

        @message.push "<tr>"
        @message.push "<th>"
        @message.push "Autoryzowane ogółem"
        @message.push "</th>"
        @message.push "<th>"
        @message.push "Autoryzowane w ostatnim miesiącu"
        @message.push "</th>"
        @message.push "<th>"
        @message.push "Kody próbek autoryzowane w ostatnim miesiącu"
        @message.push "</th>"
        @message.push "</tr>"

        samples.each do |smp|
          @message.push "<tr>"
          @message.push "<td>"
          @message.push smp.total
          @message.push "</td>"
          @message.push "<td>"
          @message.push smp.last_month
          @message.push "</td>"
          @message.push "<td>"
          @message.push smp.last_month_codes
          @message.push "</td>"
          @message.push "</tr>"
        end

        @message.push "</table>"
        @message.push "<hr>"
      end

      def add_monthly_order(order_name, arr)
        date_start = (Time.now - 1.month).at_beginning_of_month
        date_end = (Time.now - 1.month).at_end_of_month
        ord = Sample.where(Code: arr).where(AcceptanceDate: date_start..date_end)

        @monthly_orders << OpenStruct.new(name: order_name, acc_count: ord.size, nonreg_count: Sample.where(Code: arr, PatientId: 4798).count, balance: "#{Sample.where(Code: arr).where.not(AcceptanceDate: nil).count} / #{arr.count}")
      end

      def add_general_order(order_name, arr)
        ord = Sample.where(Code: arr)
        auth = Measurement.where(SampleId: ord.pluck(:Id), Status: 5).order(:SampleId).count

        @general_orders << OpenStruct.new(name: order_name, online_count: ord.where(AcceptanceDate: nil).count, cancelled: ord.where(soaking_degree_id: [4,5]).count, authorized: auth, nonreg_count: ord.where(PatientId: 4798).count, balance: "#{ord.where.not(AcceptanceDate: nil).count} / #{arr.count}")
      end

      def add_omega_samples()
        date_start = (Time.now - 1.month).at_beginning_of_month
        date_end = (Time.now - 1.month).at_end_of_month
        total = Measurement.includes(sample: {patient: :contractor}).where(Status: 5, ProjectId: 21).where(sample: {patient: {Contractors: {institution_id: 33}}}).pluck(:SampleId).uniq.count
        last_month = Measurement.includes(sample: {patient: :contractor}).where(Status: 5, ProjectId: 21, AuthorizedAt: date_start..date_end).where(sample: {patient: {Contractors: {institution_id: 33}}}).pluck(:SampleId).uniq.count
        last_month_codes = Measurement.includes(sample: {patient: :contractor}).where(Status: 5, ProjectId: 21, AuthorizedAt: date_start..date_end).where(sample: {patient: {Contractors: {institution_id: 33}}}).pluck("sample.Code").uniq.join(", ")
        @omega_samples << OpenStruct.new(total: total, last_month: last_month, last_month_codes: last_month_codes)
      end



